#include <vector>
#include <unordered_map>
#include <cstdint>

struct Order { uint64_t id; uint32_t qty; int32_t tick; Order* prev; Order* next; bool buy; };

struct Level { uint64_t total = 0; Order* head = nullptr; Order* tail = nullptr; };

class OrderBook {
public:
    OrderBook(int nticks) : levels_(nticks) {}

    void add(uint64_t id, bool buy, int32_t tick, uint32_t qty) {
        Order* o = pool_.alloc();                 // pre-allocated pool, no new
        *o = {id, qty, tick, nullptr, nullptr, buy};
        Level& L = levels_[tick];
        o->prev = L.tail;                         // append => time priority
        (L.tail ? L.tail->next : L.head) = o;
        L.tail = o; L.total += qty;
        index_[id] = o;
        if (buy)  best_bid_ = std::max(best_bid_, tick);
        else      best_ask_ = std::min(best_ask_, tick);
    }

    void cancel(uint64_t id) {
        auto it = index_.find(id); if (it == index_.end()) return;
        Order* o = it->second; Level& L = levels_[o->tick];
        (o->prev ? o->prev->next : L.head) = o->next;
        (o->next ? o->next->prev : L.tail) = o->prev;
        L.total -= o->qty; index_.erase(it); pool_.free(o);
        if (L.total == 0) reseat_touch(o->tick, o->buy);   // advance best bid/ask
    }

    int32_t best_bid() const { return best_bid_; }
    int32_t best_ask() const { return best_ask_; }
private:
    void reseat_touch(int32_t emptied, bool buy);   // scan/bitset to next active level
    std::vector<Level> levels_;
    std::unordered_map<uint64_t, Order*> index_;    // prefer a custom open-addressing map
    int32_t best_bid_ = -1, best_ask_ = INT32_MAX;
    struct Pool { Order* alloc(); void free(Order*); } pool_;
};

// Exchange-accurate modify: size-decrease keeps queue priority; price change or
// size-increase loses priority (treated as cancel + new at the back of the queue).
void OrderBook::modify(uint64_t id, int32_t newTick, uint32_t newQty) {
    auto it = index_.find(id); if (it == index_.end()) return;
    Order* o = it->second;
    const bool keepsPriority = (newTick == o->tick) && (newQty <= o->qty);
    if (keepsPriority) {                       // in-place size reduction
        levels_[o->tick].total -= (o->qty - newQty);
        o->qty = newQty;
    } else {                                   // re-queue: lose time priority
        bool buy = o->buy; cancel(id); add(id, buy, newTick, newQty);
    }
}

#include <bit>
// populated_[i] bit set iff levels_[i].total > 0. After the bid touch empties:
int32_t OrderBook_next_bid(const uint64_t* words, int32_t from) {
    // scan downward for the highest set bit <= from (find-last-set per word)
    for (int32_t w = from >> 6; w >= 0; --w) {
        uint64_t bits = words[w];
        if (w == (from >> 6)) bits &= (~0ull >> (63 - (from & 63))); // mask above 'from'
        if (bits) return (w << 6) + (63 - std::countl_zero(bits));
    }
    return -1;   // empty side
}

#include <bit>
#include <cstdint>
// words[]: bit i set iff level i has resting size. Find highest active level <= 'from' (bids).
int next_active_bid(const uint64_t* words, int from) {
    int w = from >> 6;
    uint64_t bits = words[w] & (~0ull >> (63 - (from & 63))); // mask bits above 'from'
    if (bits) return (w << 6) + (63 - std::countl_zero(bits));
    for (--w; w >= 0; --w)
        if (words[w]) return (w << 6) + (63 - std::countl_zero(words[w]));
    return -1; // empty side
}
